-- Step BA-2: the three French door VARIANT templates.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
-- Run AFTER sql/step-ba1 (and after the Step AZ files az1-az4, which are
-- already live).
--
-- Integrate's own templates, from its Door group "2. Open Out Doors"
-- (docs/integrate-L31115-french-doors.txt, variants section):
--
--    79  "French Doors with Panels"                 1399 x 2199
--          -> GlazePro "French Doors With Panels"
--    29  "French Door W Lights - Attached Bottom
--         and Top Rail"                             2814 x 2710
--          -> "French Doors With Side And Top Lights"
--    46  "French Door Set W Casement Lights"        2814 x 2710
--          -> "French Door Set With Casement Lights"
--
-- Each tree was GENERATED by the board's own code
-- (buildPanelledFrenchDoorFrame and buildFrenchDoorSetFrame), so each
-- template is exactly what the board would build and assertSaveable passes
-- on it.
--
-- TEMPLATE 79. Each leaf carries a MID RAIL (a transomPart inside the leaf,
-- isMidrail, 170) with glass above it and a raised-and-fielded Tricoya panel
-- below, ovolo bead both sides. The rail is placed so the PANEL is 425 deep
-- — Integrate stores the glass height instead (1241) and lets the panel
-- absorb a resize; at template 79's own size the two agree exactly, and
-- GlazePro's way means a template built at any size starts with the same
-- panel. A later resize keeps the stored offset, as Integrate's does.
--
-- TEMPLATES 29 AND 46. A frame with two full-height mullions and a
-- full-width transom: the pair in the middle bottom opening, a FIXED
-- casement side light each side, and a top row of three direct glazed units
-- (29) or three fixed casement fanlights (46).
--
--   MULLIONS ARE SYMMETRICAL, which Integrate's own template is not: its 29
--   has side columns of 648 and 651. Nathan's drawings are symmetrical, so
--   the board splits what is left after the middle opening equally and puts
--   the odd millimetre in the MIDDLE, where no one can see it:
--     internal 2720 = 649 + 41 + 1340 + 41 + 649
--   so each side light is 647 x 2134 (Integrate 646 and 649) and each leaf
--   680 x 2131 (Integrate 679.5). Said out loud in docs/reports/step-ba.md.
--
--   The three TOP lights take Nathan's 62 bottom rail, as every new GlazePro
--   fanlight does (difference 5); the two SIDE lights keep Integrate's 86,
--   which is what its templates draw and what the FD5 / FD6 benchmarks
--   price. On template 46 that moves three rails from the Utile63x96 section
--   to Utile63x63 (difference 7b).
--
--   The direct glazed units have Integrate's 15 mm clearance all round and
--   12 mm hidden in the rebate. Integrate's own A1 stores hidden 0 — a
--   template quirk the FD5 FIXTURE keeps, because a fixture's job is
--   Integrate's figures, and which GlazePro's template does not copy.
--
-- NO stored ironmongery list and NO stored surround list, as every GlazePro
-- template since Step AX: the default rules price both from the drawing
-- (differences 4, 9 and 10 in docs/integrate-differences.md).
--
-- Product and Quantity are both is_required (Step AQ), so the product code is
-- looked up BY LABEL and the script fails loudly rather than writing a code
-- that would look set and still fail the check.
--
-- RUN SECTION 0 FIRST.

-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 0 — read before changing
-- ═══════════════════════════════════════════════════════════════════════════

-- 0a. The door templates as they stand (Step AZ's two should be here).
SELECT id, name, family, group_name, window_type, sort_order, is_active
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order, name;

-- 0b. Do any of this step's three names already exist? A re-run updates
--     them in place; anything else here is somebody else's template.
SELECT id, name, sort_order, is_active, updated_at
FROM   public.drawing_templates
WHERE  name IN (
    'French Doors With Panels',
    'French Doors With Side And Top Lights',
    'French Door Set With Casement Lights'
)
ORDER  BY name;

-- 0c. The panel OPTION rows the board's panel panel would offer. The trees
--     below store 'raised_and_fielded' and 'ovolo' (Integrate's own defaults
--     110 and 120). The engine maps both those codes and Integrate's numeric
--     ids, so the panels price either way — but if these categories are
--     empty the board has nothing to pick from, and the reviewer needs to
--     know. NOT VERIFIED either way at the time of writing.
SELECT category, code, label, sort_order, is_active
FROM   reference_options
WHERE  category IN ('panel_type', 'panel_bead')
ORDER  BY category, sort_order;

-- 0d. The containment pairs sql/step-ba1 adds. Expect 4 rows; if there are
--     none, run step-ba1 first — the DO block below refuses anyway.
SELECT parent_code, child_code, min_count, max_count
FROM   part_type_children
WHERE  parent_code IN ('leftFrenchDoorLeafPart', 'rightFrenchDoorLeafPart')
  AND  child_code  IN ('transomPart', 'panelPart')
ORDER  BY parent_code, child_code;


-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 1 — the three templates
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

DO $$
DECLARE
  _profile_id bigint;
  _door_code  text;
  _templates  jsonb := '[{"name":"French Doors With Panels","sort_order":30,"tree":{"key":"item_573vy1g","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_rej82x1","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_59622cn","part_type":"notesPart","values":{},"children":[]},{"key":"price_es9jc6a","part_type":"pricePart","values":{},"children":[]},{"key":"frame_clzff2e","part_type":"assemblyFramePart","values":{"width":1399,"height":2199,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_s5rwfrt","part_type":"frenchDoorPart","values":{"casementTypeId":"open_out","thickness":54,"midRail":198,"gapBetweenMeetingStiles":5,"meetingStileOverlap":27,"mechanicalClearanceTop":3,"mechanicalClearanceBottom":3,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"masterLeaf":"right"},"children":[{"key":"frenchdoor_s5rwfrt_left","part_type":"leftFrenchDoorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_s5rwfrt_left_midrail","part_type":"transomPart","values":{"isMidrail":true,"offset":1241,"thicknessInFrame":170,"midrailThickness":170,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"frenchdoor_s5rwfrt_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]},{"key":"frenchdoor_s5rwfrt_left_panel","part_type":"panelPart","values":{"internalPanelTypeId":"raised_and_fielded","externalPanelTypeId":"raised_and_fielded","internalPanelBeadId":"ovolo","externalPanelBeadId":"ovolo","insulationThickness":15,"createVisionPanel":true,"panelThickness":0,"toBeReplaced":true},"children":[]}]},{"key":"frenchdoor_s5rwfrt_right","part_type":"rightFrenchDoorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"frenchdoor_s5rwfrt_right_midrail","part_type":"transomPart","values":{"isMidrail":true,"offset":1241,"thicknessInFrame":170,"midrailThickness":170,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"frenchdoor_s5rwfrt_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]},{"key":"frenchdoor_s5rwfrt_right_panel","part_type":"panelPart","values":{"internalPanelTypeId":"raised_and_fielded","externalPanelTypeId":"raised_and_fielded","internalPanelBeadId":"ovolo","externalPanelBeadId":"ovolo","insulationThickness":15,"createVisionPanel":true,"panelThickness":0,"toBeReplaced":true},"children":[]}]}]},{"key":"cill_twcyq2r","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}},{"name":"French Doors With Side And Top Lights","sort_order":40,"tree":{"key":"item_mwrdbzb","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_egdyd0k","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_bi0mp4y","part_type":"notesPart","values":{},"children":[]},{"key":"price_r4fqogy","part_type":"pricePart","values":{},"children":[]},{"key":"frame_pve2vd2","part_type":"assemblyFramePart","values":{"width":2814,"height":2710,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"mull_5yenh7c","part_type":"mullionPart","values":{"offset":649,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"mull_lvr2fgq","part_type":"mullionPart","values":{"offset":2030,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"trans_1joh4v6","part_type":"transomPart","values":{"offset":448,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"glass_bx5igjs","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3,"mechanicalClearanceTop":15,"mechanicalClearanceBottom":15,"mechanicalClearanceLeft":15,"mechanicalClearanceRight":15,"hiddenInRebateTop":12,"hiddenInRebateBottom":12,"hiddenInRebateLeft":12,"hiddenInRebateRight":12,"toBeReplaced":true},"children":[]},{"key":"glass_bb8doam","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3,"mechanicalClearanceTop":15,"mechanicalClearanceBottom":15,"mechanicalClearanceLeft":15,"mechanicalClearanceRight":15,"hiddenInRebateTop":12,"hiddenInRebateBottom":12,"hiddenInRebateLeft":12,"hiddenInRebateRight":12,"toBeReplaced":true},"children":[]},{"key":"glass_cm083u4","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3,"mechanicalClearanceTop":15,"mechanicalClearanceBottom":15,"mechanicalClearanceLeft":15,"mechanicalClearanceRight":15,"hiddenInRebateTop":12,"hiddenInRebateBottom":12,"hiddenInRebateLeft":12,"hiddenInRebateRight":12,"toBeReplaced":true},"children":[]},{"key":"cas_v4o7onq","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_v4o7onq_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_fz970mf","part_type":"frenchDoorPart","values":{"casementTypeId":"open_out","thickness":54,"midRail":198,"gapBetweenMeetingStiles":5,"meetingStileOverlap":27,"mechanicalClearanceTop":3,"mechanicalClearanceBottom":3,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"masterLeaf":"right"},"children":[{"key":"frenchdoor_fz970mf_left","part_type":"leftFrenchDoorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_fz970mf_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_fz970mf_right","part_type":"rightFrenchDoorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"frenchdoor_fz970mf_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]}]},{"key":"cas_3p02dpb","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_3p02dpb_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_0wld4qa","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}},{"name":"French Door Set With Casement Lights","sort_order":50,"tree":{"key":"item_i1eab2s","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_8zohd4a","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_xk76q0z","part_type":"notesPart","values":{},"children":[]},{"key":"price_uiv38vm","part_type":"pricePart","values":{},"children":[]},{"key":"frame_5tvn0cx","part_type":"assemblyFramePart","values":{"width":2814,"height":2710,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"mull_rlv53wq","part_type":"mullionPart","values":{"offset":649,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"mull_k6a3v0u","part_type":"mullionPart","values":{"offset":2030,"thicknessInFrame":41,"mullionStopSize":20},"children":[]},{"key":"trans_zrgh96w","part_type":"transomPart","values":{"offset":448,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_3la5nno","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_3la5nno_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_k5bbgyi","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_k5bbgyi_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_hclddqj","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_hclddqj_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cas_nng7i7d","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_nng7i7d_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_ec1ze7t","part_type":"frenchDoorPart","values":{"casementTypeId":"open_out","thickness":54,"midRail":198,"gapBetweenMeetingStiles":5,"meetingStileOverlap":27,"mechanicalClearanceTop":3,"mechanicalClearanceBottom":3,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"masterLeaf":"right"},"children":[{"key":"frenchdoor_ec1ze7t_left","part_type":"leftFrenchDoorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"frenchdoor_ec1ze7t_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"frenchdoor_ec1ze7t_right","part_type":"rightFrenchDoorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"frenchdoor_ec1ze7t_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]}]},{"key":"cas_kztk8lx","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_kztk8lx_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_40hlseb","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}}]'::jsonb;
  _row        record;
  _tree       jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'open_out_doors' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''open_out_doors'' — the door profile must exist first';
  END IF;

  SELECT code INTO _door_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'french door' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _door_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''French Door'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  -- A template that cannot be saved is worse than no template.
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'leftFrenchDoorLeafPart' AND child_code = 'panelPart'
  ) THEN
    RAISE EXCEPTION 'Containment for a PANELLED door leaf is missing — run sql/step-ba1-door-variant-containment.sql first';
  END IF;

  -- And a door with no sections prices no timber at all, which would look
  -- like a working template and quote hundreds of pounds short.
  IF NOT EXISTS (
    SELECT 1 FROM parts_catalogue WHERE part_code = 'Utile67x96' AND is_active
  ) THEN
    RAISE EXCEPTION 'The Utile stock sections are missing — run sql/step-az1-utile-section-parts.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 3 THEN
    RAISE EXCEPTION 'Expected 3 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_door_code), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id,
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step BA-2: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'door', 'Open Out Doors', 'French Door',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step BA-2: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. All five door templates, with Product and Quantity set.
SELECT name, family, group_name, window_type, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity,
       tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order;

-- 2. Each new template's shape. Expect:
--      Panels            1 pair, 2 leaves, 0 mullions, 2 transoms (the mid
--                        rails, both inside leaves), 2 panels, 0 sashes
--      Side And Top      1 pair, 2 leaves, 2 mullions, 1 transom, 0 panels,
--                        2 casement sashes (the side lights), 5 glass parts
--      Casement Lights   1 pair, 2 leaves, 2 mullions, 1 transom, 0 panels,
--                        5 casement sashes
SELECT t.name,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "frenchDoorPart")'))          AS pairs,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "leftFrenchDoorLeafPart")'))  AS left_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "mullionPart")'))             AS mullions,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")'))             AS transoms,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "panelPart")'))               AS panels,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "casementSashPart")'))        AS casement_sashes,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "glassPart")'))               AS glass_parts
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Panels',
    'French Doors With Side And Top Lights',
    'French Door Set With Casement Lights'
)
ORDER  BY t.sort_order;

-- 3. The panelled template's mid rails and panels: expect offset 1241,
--    isMidrail true, and raised_and_fielded / ovolo on both sides.
SELECT (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.isMidrail == true).offset') v)        AS mid_rail_offsets,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.isMidrail == true).midrailThickness') v) AS mid_rail_thickness,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.internalPanelTypeId') v)                   AS panel_types,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.internalPanelBeadId') v)                   AS panel_beads
FROM   public.drawing_templates t
WHERE  t.name = 'French Doors With Panels';

-- 4. The doorsets' dividers and bottom rails: expect mullion offsets
--    649 and 2030, a transom at 448, and bottom rails of 86 on the two side
--    lights with 62 on the three top lights of template 46.
SELECT t.name,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mullionStopSize > 0).offset') v) AS mullion_offsets,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values ? (@.transomStopSize == 18).offset') v)               AS transom_offsets,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.operation == "fix").bottomHeight') v) AS fixed_sash_rails
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Side And Top Lights',
    'French Door Set With Casement Lights'
)
ORDER  BY t.sort_order;

-- 5. None of the three carries a stored surround or ironmongery list, and
--    all three are utile. Expect NULL, NULL, utile.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.ironmongeryLines') v) AS ironmongery,
       t.tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates t
WHERE  t.name IN (
    'French Doors With Panels',
    'French Doors With Side And Top Lights',
    'French Door Set With Casement Lights'
)
ORDER  BY t.sort_order;


